-- Real, isolated Supabase schema. All fixtures, intentions and decisions roll back.
begin;
create function pg_temp.d_id(n int) returns uuid language sql as $$ select ('f1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid; $$;
create function pg_temp.d_actor(n int) returns void language sql as $$ select set_config('request.jwt.claim.sub',pg_temp.d_id(n)::text,true); $$;
create function pg_temp.d_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'D FAIL: %',label; end if; end; $$;
create function pg_temp.d_error(sql text,code text) returns void language plpgsql as $$ begin begin execute sql; exception when others then if sqlstate=code then return; end if; raise; end; raise exception 'D expected %',code; end; $$;
create function pg_temp.d_cmd(cmd text,payload jsonb) returns jsonb language sql as $$ select public.passport_command(cmd,payload,gen_random_uuid()); $$;
create function pg_temp.d_keep(key text,val jsonb) returns void language sql as $$ select set_config('passport.d.'||key,val->>'id',true); $$;
create function pg_temp.d_ref(key text) returns uuid language sql as $$ select current_setting('passport.d.'||key)::uuid; $$;
create function pg_temp.d_media(attempt_key text,stage text) returns jsonb language sql as $$
 select public.passport_provider_event('media',gen_random_uuid()::text,jsonb_build_object('order_id',pg_temp.d_ref('order'),'attempt_id',pg_temp.d_ref(attempt_key),'stage',stage,'provider','mock','provider_reference','mock:d:'||attempt_key,'duration_seconds',80,'bytes',12000,'mime_type','video/mp4'));
$$;
create function pg_temp.d_review(outcome text) returns jsonb language sql as $$
 select jsonb_build_object('order_id',pg_temp.d_ref('order'),'outcome',outcome,'observations','Observed consistent preparation and controlled feeds.',
 'positive_feedback','Good ready position and preparation.','areas_for_improvement','Contact needs to stay in front.','practice_tasks',jsonb_build_array('Ten controlled feeds before recovery.'),'next_step','Practise contact and recovery before reassessment.',
 'criteria_results',jsonb_build_object('position',true,'contact',outcome='verified'),'replacement_reason','Incorrect camera angle','recording_guidance','Film from behind with full body and contact visible.');
$$;
insert into auth.users(id) select pg_temp.d_id(i) from generate_series(1,5) i;
update public.profiles set full_name='Synthetic D player' where id=pg_temp.d_id(2);
update public.profiles set full_name='Synthetic D assessor' where id=pg_temp.d_id(3);
insert into public.coaches(id,name,is_approved) values(pg_temp.d_id(9),'Synthetic D coach',true);
insert into public.coach_memberships(coach_id,user_id) values(pg_temp.d_id(9),pg_temp.d_id(3)),(pg_temp.d_id(9),pg_temp.d_id(4));
insert into public.admin_memberships(user_id,role,status) values(pg_temp.d_id(1),'owner','active'),(pg_temp.d_id(5),'support','active');
set local role authenticated; select pg_temp.d_actor(2);
select pg_temp.d_error($q$select public.passport_review_context(array[pg_temp.d_id(20)])$q$,'42501');
reset role; update private.pp_runtime set enabled=true;
set local role authenticated; select pg_temp.d_actor(1);
select pg_temp.d_cmd('publish_standard','{"id":"a0000000-0000-4000-8000-000000000002","reason":"Synthetic D approval of sample rubric"}');
select pg_temp.d_cmd('publish_policy','{"id":"c0000000-0000-4000-8000-000000000001","reason":"Synthetic D local policy approval"}');
select pg_temp.d_keep('grant',pg_temp.d_cmd('set_assessor',jsonb_build_object('coach_id',pg_temp.d_id(9),'assessor_user_id',pg_temp.d_id(3),'skill_id','improver-bandeja','credential_reference','mock:d','status','approved','credentials_verified',true,'reason','Synthetic D credential review')));
select pg_temp.d_actor(3);
select pg_temp.d_keep('offer',pg_temp.d_cmd('create_offer',jsonb_build_object('grant_id',pg_temp.d_ref('grant'),'standard_id','a0000000-0000-4000-8000-000000000002','price_minor',3500,'currency','GBP')));
select pg_temp.d_actor(2);
select pg_temp.d_keep('order',pg_temp.d_cmd('create_order',jsonb_build_object('offer_id',pg_temp.d_ref('offer'),'policy_id','c0000000-0000-4000-8000-000000000001')));
select pg_temp.d_error($q$select public.passport_save_submission_note(pg_temp.d_ref('order'),'unfunded notes')$q$,'23514');
reset role; set local role service_role;
select public.passport_provider_event('payment','d:paid',jsonb_build_object('order_id',pg_temp.d_ref('order'),'amount_minor',3500,'currency','GBP','payment_reference','mock:d:paid'));
reset role; set local role authenticated; select pg_temp.d_actor(2);
select public.passport_save_submission_note(pg_temp.d_ref('order'),'How can I improve my contact point?');
select pg_temp.d_assert(public.passport_review_context(array[pg_temp.d_ref('order')])->0->>'player_name'='Synthetic D player','owner can read selected identity');
select pg_temp.d_assert(public.passport_review_context(array[pg_temp.d_ref('order')])->0->>'player_notes'='How can I improve my contact point?','notes returned privately');
select pg_temp.d_assert(not (public.passport_review_context(array[pg_temp.d_ref('order')])->0 ? 'email'),'context omits contact data');
select pg_temp.d_actor(4);
select pg_temp.d_assert(jsonb_array_length(public.passport_review_context(array[pg_temp.d_ref('order')]))=0,'ordinary approved coach/member sees no context');
select pg_temp.d_error($q$select public.passport_save_submission_note(pg_temp.d_ref('order'),'Forged coach notes')$q$,'42501');
select pg_temp.d_error($q$select pg_temp.d_cmd('submit_review',pg_temp.d_review('verified'))$q$,'42501');
select pg_temp.d_actor(2);
select pg_temp.d_error($q$select pg_temp.d_cmd('submit_review',pg_temp.d_review('verified'))$q$,'42501');
select pg_temp.d_keep('a1',pg_temp.d_cmd('begin_attempt',jsonb_build_object('order_id',pg_temp.d_ref('order'))));
select pg_temp.d_error($q$select public.passport_save_submission_note(pg_temp.d_ref('order'),'Changed after upload')$q$,'23514');
reset role; set local role service_role;
select pg_temp.d_media('a1','uploaded'); select pg_temp.d_media('a1','processing'); select pg_temp.d_media('a1','ready');
reset role; select pg_temp.d_assert((select count(*)=1 from private.pp_notification_intents where kind='review_ready'),'one ready intention');
set local role authenticated; select pg_temp.d_actor(3);
select pg_temp.d_assert(jsonb_array_length(public.passport_review_context(array[pg_temp.d_ref('order')]))=1,'assigned assessor context');
select pg_temp.d_error($q$select pg_temp.d_cmd('submit_review',pg_temp.d_review('developing')||'{"positive_feedback":"short"}'::jsonb)$q$,'23514');
select pg_temp.d_cmd('start_review',jsonb_build_object('order_id',pg_temp.d_ref('order')));
select public.passport_command('submit_review',pg_temp.d_review('replacement_requested'),pg_temp.d_id(30));
select public.passport_command('submit_review',pg_temp.d_review('replacement_requested'),pg_temp.d_id(30));
select pg_temp.d_assert((select state='replacement_requested' and completed_at is null and review_due_at is null from public.pp_orders where id=pg_temp.d_ref('order')),'replacement pauses clock and is not delivery');
select pg_temp.d_actor(2); select pg_temp.d_keep('a2',pg_temp.d_cmd('begin_attempt',jsonb_build_object('order_id',pg_temp.d_ref('order'))));
reset role; set local role service_role;
select pg_temp.d_media('a2','uploaded'); select pg_temp.d_media('a2','processing'); select pg_temp.d_media('a2','ready');
reset role; set local role authenticated; select pg_temp.d_actor(3);
select pg_temp.d_cmd('submit_review',pg_temp.d_review('replacement_requested'));
select pg_temp.d_actor(1);
select pg_temp.d_assert((select replacement_count=2 from public.pp_replacement_watch where order_id=pg_temp.d_ref('order')),'two replacement requests visible to admin');
select pg_temp.d_actor(5);
select pg_temp.d_assert((select count(*)=0 from public.pp_replacement_watch),'support cannot read replacement watch');
select pg_temp.d_error($q$select public.passport_notification_preview()$q$,'42501');
select pg_temp.d_error($q$select public.passport_prepare_deadline_notifications()$q$,'42501');
select pg_temp.d_actor(2); select pg_temp.d_keep('a3',pg_temp.d_cmd('begin_attempt',jsonb_build_object('order_id',pg_temp.d_ref('order'))));
reset role; set local role service_role;
select pg_temp.d_media('a3','uploaded'); select pg_temp.d_media('a3','processing'); select pg_temp.d_media('a3','ready');
reset role; update public.pp_orders set review_due_at=clock_timestamp()+interval '2 hours' where id=pg_temp.d_ref('order');
set local role authenticated; select pg_temp.d_actor(1);
select pg_temp.d_assert(public.passport_prepare_deadline_notifications()=1,'approaching deadline intention');
select pg_temp.d_assert(public.passport_prepare_deadline_notifications()=0,'repeated deadline preparation idempotent');
reset role; update public.pp_orders set review_due_at=clock_timestamp()-interval '2 hours' where id=pg_temp.d_ref('order');
set local role authenticated; select pg_temp.d_actor(1);
select pg_temp.d_assert(public.passport_prepare_deadline_notifications()=1,'overdue intention');
select pg_temp.d_cmd('set_assessor',jsonb_build_object('id',pg_temp.d_ref('grant'),'status','suspended','reason','Synthetic D suspension check'));
select pg_temp.d_actor(3);
select pg_temp.d_assert(jsonb_array_length(public.passport_review_context(array[pg_temp.d_ref('order')]))=0,'suspension removes identity context');
select pg_temp.d_error($q$select pg_temp.d_cmd('submit_review',pg_temp.d_review('verified'))$q$,'42501');
select pg_temp.d_actor(1);
select pg_temp.d_cmd('set_assessor',jsonb_build_object('id',pg_temp.d_ref('grant'),'status','approved','credentials_verified',true,'reason','Synthetic D reapproval for final test'));
select pg_temp.d_actor(3);
select public.passport_command('submit_review',pg_temp.d_review('verified'),pg_temp.d_id(31));
select public.passport_command('submit_review',pg_temp.d_review('verified'),pg_temp.d_id(31));
select pg_temp.d_error($q$select pg_temp.d_cmd('submit_review',pg_temp.d_review('developing'))$q$,'23514');
select pg_temp.d_actor(2);
select pg_temp.d_assert((select latest_outcome='verified' and active_verification_count=1 from public.pp_passport_skill_records where skill_id='improver-bandeja'),'atomic Passport update');
select pg_temp.d_assert((select count(*)=1 from public.pp_skill_verifications where order_id=pg_temp.d_ref('order')),'unique verification');
select pg_temp.d_assert((select count(*)=3 from public.pp_submission_attempts where order_id=pg_temp.d_ref('order')),'all free replacement history retained');
select pg_temp.d_assert((select payment_reference='mock:d:paid' from public.pp_orders where id=pg_temp.d_ref('order')),'no second payment');
select pg_temp.d_actor(4);
select pg_temp.d_assert((select count(*)=0 from public.pp_reviews where order_id=pg_temp.d_ref('order')),'other account cannot read feedback');
reset role;
select pg_temp.d_assert((select count(*)=1 from private.pp_notification_intents where kind='assessment_completed'),'duplicate completion produces one completion intention');
select pg_temp.d_assert((select count(*)=1 from private.pp_notification_intents where kind='skill_verified'),'one verification intention');
select pg_temp.d_assert((select count(*)=2 from private.pp_notification_intents where kind='replacement_requested'),'one intention per actual replacement decision');
select pg_temp.d_assert((select count(*)=count(distinct event_key) from private.pp_notification_intents),'all notification event keys unique');
rollback;
